  async start(){if(PWA.on)return;try{const c=JSON.parse(localStorage.getItem('lifeos-gcal')||'null');if(c&&c.events){this.events=c.events;this.last=c.at;}}catch(e){}if(get.settings().calendar.on)this.sync();},
