      if(!this.mcp){this.status='error';this.msg=PWA.on?'Google Calendar in the home-screen app is coming in a later update. It still works in Life OS on claude.ai.':'Calendar isn’t available in this view. Open Life OS on claude.ai.';App.refresh();return;}
