      for(let i=0;i<8;i++){const input={startTime:`${from}T00:00:00`,endTime:`${to}T23:59:59`,pageSize:250,orderBy:'startTime'};if(token)input.pageToken=token;const res=await this.mcp.callTool('Google Calendar','list_events',input);const p=res.payload||{};out=out.concat((p.events||[]).map(e=>({id:e.id,summary:e.summary,start:e.start,end:e.end,status:e.status,attendees:(e.attendees||[]).filter(a=>a.self).map(a=>({self:true,responseStatus:a.responseStatus})),location:e.location,htmlLink:e.htmlLink})));token=p.nextPageToken;if(!token)break;}
